import { NextResponse, type NextRequest } from 'next/server'

export function proxy(request: NextRequest) {
  // Generate a unique id for this request (available in the Edge Runtime).
  const requestId = crypto.randomUUID()

  console.log(`[middleware] request pathname: ${request.nextUrl.pathname}`)

  const response = NextResponse.next({
    request: {
      headers: request.headers,
    },
  // Custom headers set here are applied to the response that reaches the client.
  headers: {
    'X-Request-Id': requestId,
    },
  })

  return response
}

export const config = {
  // Run on every route. The negative lookahead excludes Next.js internals
  // (static assets and the Next.js image optimizer) so the middleware
  // doesn't add overhead where it isn't needed.
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
}
